    66  bool abstract_actor_shell::consume_message() {
    67    auto lg = log::net::trace("");
    68    if (auto msg = next_message()) {
    69      current_element_ = msg.get();
    70      CAF_LOG_RECEIVE_EVENT(current_element_);
    71      auto mid = msg->mid;
    72      if (!mid.is_response()) {
    73        detail::default_invoke_result_visitor<abstract_actor_shell> visitor{this};
    74        if (auto result = bhvr_(msg->payload)) {
    75          visitor(*result);
    76        } else {
    77          auto fallback_result = (*fallback_)(this, msg->payload);
    78          visit(visitor, fallback_result);
    79        }
    80      } else if (auto i = multiplexed_responses_.find(mid);
    81                 i != multiplexed_responses_.end()) {
    82        auto [bhvr, pending_timeout] = std::move(i->second);
    83        pending_timeout.dispose();
    84        multiplexed_responses_.erase(i);
    85        auto res = bhvr(msg->payload);
    86        if (!res) {
    87          log::net::debug("got unexpected_response");
    88          auto err_msg = make_message(
    89            make_error(sec::unexpected_response, std::move(msg->payload)));
    90          bhvr(err_msg);
    91        }
    92      }
    93      CAF_LOG_SKIP_OR_FINALIZE_EVENT(invoke_message_result::consumed);
    94      return true;
    95    }
    96    return false;
    97  }
